- Define your document as a state.
- Define your editor view declaratively. There are rules you have to follow:
  - You must render all texts in the document as Text nodes in DOM.
  - You must render <br/> in empty blocks (limitation of contenteditable).
  - You must render hard breaks in the document as block element.
  - You must render void nodes in the document as void element.
- Use createPlainEditor /createEditor to initializeEditor with the document.
- Call Editor.input on mount, withHTMLElement which is the root of editor view.
- Update your state with onChange , which will be called on edit.
- Call returned function from Editor.input on unmount for cleanup.
Here is an example for React.
import { useState, useEffect, useRef } from "react";
import { createPlainEditor } from "editate";
export const App = () => {
  const ref = useRef<HTMLDivElement>(null);
  // 1. Define state
  const [text, setText] = useState("Hello world.");
  useEffect(() => {
    // 3. init
    const editor = createPlainEditor({
      text: text,
      onChange: (v) => {
        // 5. update state
        setText(v);
      },
    });
    // 4. bind to DOM
    const cleanup = editor.input(ref.current);
    return () => {
      // 6. cleanup DOM
      cleanup();
    };
  }, []);
  // 2. render from state
  return (
    <div
      ref={ref}
      style={{
        backgroundColor: "white",
        border: "solid 1px darkgray",
        padding: 8,
      }}
    >
      {text.split("\n").map((t, i) => (
        <div key={i}>{t ? t : <br />}</div>
      ))}
    </div>
  );
};
You can define document schema with Standard Schema for type-safe editing.
import { useState, useEffect, useRef, useMemo } from "react";
import {
  createEditor,
  plainTransferPlugin,
  ToggleFormat,
  ToggleBlockAttr,
} from "editate";
import * as z from "zod";
const schema = z.strictObject({
  children: z.array(
    z.strictObject({
      align: z.enum(["left", "right"]).optional(),
      children: z.array(
        z.strictObject({
          text: z.string(),
          bold: z.boolean().optional(),
          italic: z.boolean().optional(),
        }),
      ),
    }),
  ),
});
export const App = () => {
  const ref = useRef<HTMLDivElement>(null);
  type Doc = z.infer<typeof schema>;
  const [doc, setDoc] = useState<Doc>({
    children: [
      {
        children: [
          { text: "Hello", bold: true },
          { text: " " },
          { text: "World", italic: true },
          { text: "." },
        ],
      },
    ],
  });
  const editor = useMemo(() => {
    const e = createEditor({
      doc,
      schema,
    }).exec(plainTransferPlugin);
    e.on("change", () => {
      setDoc(e.doc);
    });
    return e;
  }, []);
  useEffect(() => {
    return editor.input(ref.current);
  }, []);
  return (
    <div>
      <div>
        <button
          onClick={() => {
            editor.exec(ToggleFormat, "bold");
          }}
        >
          bold
        </button>
        <button
          onClick={() => {
            editor.exec(ToggleFormat, "italic");
          }}
        >
          italic
        </button>
        <button
          onClick={() => {
            editor.exec(ToggleBlockAttr, "align", "right", undefined);
          }}
        >
          align
        </button>
      </div>
      <div
        ref={ref}
        style={{
          backgroundColor: "white",
          border: "solid 1px darkgray",
          padding: 8,
        }}
      >
        {doc.children.map((b, i) => (
          <div key={i} style={{ textAlign: b.align }}>
            {b.children.map((n, j) => (
              <span
                key={j}
                style={{
                  fontWeight: n.bold ? "bold" : undefined,
                  fontStyle: n.italic ? "italic" : undefined,
                }}
              >
                {n.text || <br />}
              </span>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
};
